const raw = String($json.Brands ?? $json.brands ?? '').trim();
if (!raw) throw new Error('Brands list is empty');

const lines = raw.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
const rows = [];
const invalid = [];
const allowed = ['US','CA','AU','UK','NL','DE','FR'];

for (const line of lines) {
  const parts = line.split('|').map(s => s.trim());
  if (parts.length !== 3 || !parts[0] || !parts[1] || !parts[2]) {
    invalid.push(line);
    continue;
  }

  const [brand, domain, countryRaw] = parts;
  const country = countryRaw.toUpperCase() === 'GB' ? 'UK' : countryRaw.toUpperCase();

  if (!allowed.includes(country)) {
    invalid.push(line + ' [unsupported country]');
    continue;
  }

  rows.push({
    brand,
    website: /^https?:\/\//i.test(domain) ? domain : 'https://' + domain + '/',
    countries: [country]
  });
}

if (!rows.length) throw new Error('No valid rows. Use: Brand|domain|country');
if (invalid.length) throw new Error('Invalid rows: ' + invalid.join(' ; '));

const batchJson = JSON.stringify(rows);

return [{
  json: {
    brandCount: rows.length,
    brands: rows.map(x => ({
      brand: x.brand,
      domain: String(x.website)
        .replace(/^https?:\/\//i, '')
        .replace(/^www\./i, '')
        .replace(/\/.*$/, ''),
      country: x.countries[0]
    })),
    batchBase64: Buffer.from(batchJson, 'utf8').toString('base64')
  }
}];

const raw = $json.stdout;
if (!raw) throw new Error('Serper search returned empty stdout');

const data = JSON.parse(raw);
const sourceRows = $('Prepare Brand List').first().json.brands ?? [];
const expected = Number($('Prepare Brand List').first().json.brandCount ?? sourceRows.length);

if ((data.searches ?? []).length !== expected) {
  const got = (data.searches ?? []).map(x => x.brand).join(', ');
  const failed = (data.failures ?? []).map(x => `${x.brand} (${x.country}): ${x.error}`).join(' | ');
  throw new Error(`Expected ${expected} brand searches but got ${(data.searches ?? []).length}. Returned: ${got || 'none'}. Failures: ${failed || 'none'}`);
}

const domainMap = new Map(
  sourceRows.map(x => [String(x.brand).trim().toLowerCase(), x.domain])
);

return (data.searches ?? []).map(search => ({
  json: {
    brand: search.brand,
    domain: domainMap.get(String(search.brand).trim().toLowerCase()) ?? '',
    country: search.country,
    results: search.results ?? [],
    resultCount: (search.results ?? []).length,
    failures: (data.failures ?? []).filter(f => f.brand === search.brand && f.country === search.country)
  }
}));

return $input.all().map(({json:item})=>{
  const full=String(item.masterPrompt??"");
  const a=full.indexOf("STEP 2 —");
  const b=full.indexOf("STEP 3 —",a+1);
  if(a<0||b<0)throw new Error("Cannot identify Step 2 boundaries in 3-in-1 prompt");
  const brand=String(item.brand||"");
  const domain=String(item.domain||"");
  const country=String(item.country||"");
  const slug=brand.toLowerCase().replace(/[^a-z0-9-]+/g,"-").replace(/^-|-$/g,"");
  const rules=full.slice(a,b).trim();
  const dealPrompt=[
    "DEAL-ONLY RESEARCH TASK — INDEPENDENT COMPARISON RUN",
    "Brand: "+brand,
    "Country: "+country,
    "Official website: https://"+domain+"/",
    "Perform ONLY official deal research. Do not extract coupon-directory codes or perform checkout/code testing.",
    "Follow all instructions below. They are the same Step-2 requirements used by the combined 3-in-1 task:",
    "",
    rules,
    "",
    "IMPORTANT: inspect the relevant official promotion/category pages before concluding no deal exists.",
    "Do not include routine delivery as a shipping discount or treat a plain newsletter form as a signup offer.",
    "OUTPUT: Generate a downloadable file named "+slug+"-deals.csv if file creation is supported.",
    "Otherwise output ONE CSV code block using the exact deal header shown above. Never output JSON.",
    "Keep every verified current offer row and exact official source URL; no invented deals or unverified numeric values."
  ].join("\n");
  return {json:{brand,domain,country,officialUrl:item.officialUrl,dealPrompt}};
});

return $input.all().map(({json:item})=>{
  const full=String(item.masterPrompt??"");
  const sourcesStart=full.indexOf("COUPON DISCOVERY SOURCES:");
  const sourcesEnd=full.indexOf("EXTRA OFFICIAL BRAND URL:",sourcesStart+1);
  const a=full.indexOf("STEP 1 —");
  const b=full.indexOf("STEP 2 —",a+1);
  if(sourcesStart<0||sourcesEnd<0||a<0||b<0)throw new Error("Cannot identify Step 1 boundaries in 3-in-1 prompt");
  const brand=String(item.brand||"");
  const domain=String(item.domain||"");
  const country=String(item.country||"");
  const slug=brand.toLowerCase().replace(/[^a-z0-9-]+/g,"-").replace(/^-|-$/g,"");
  const sourceList=full.slice(sourcesStart,sourcesEnd).trim();
  const rules=full.slice(a,b).trim();
  const couponPrompt=[
    "COUPON-ONLY EXTRACTION TASK — INDEPENDENT COMPARISON RUN",
    "Brand: "+brand,
    "Country: "+country,
    "Official brand domain (for code relevance): "+domain,
    "Perform ONLY coupon discovery on the supplied source URLs. Do not research official deals or test checkout codes.",
    "Follow all instructions below. They are the same Step-1 requirements used by the combined 3-in-1 task:",
    "",
    sourceList,
    "",
    rules,
    "",
    "IMPORTANT: extract up to 10 distinct codes PER URL, not 10 total. Complete every supplied URL before finishing.",
    "Every observed code/source pair must appear; keep same codes found across different source URLs as distinct rows.",
    "Never return only two representative examples if more were found. No fake/empty coupon rows for blocked or no_code sources.",
    "OUTPUT: Generate a downloadable file named "+slug+"-coupons.csv if file creation is supported.",
    "Otherwise return ONE CSV code block using the exact coupon header shown above. Never output JSON.",
    "If access is blocked, do not invent results or claim the source was successfully inspected."
  ].join("\n");
  return {json:{brand,domain,country,officialUrl:item.officialUrl,sourceUrlCount:item.sourceUrlCount,couponPrompt}};
});
